'use strict';
/* Module 12 · Track C · 12.15 TIU at CAT speed, 12.16 TKP I, 12.17 TKP II, 12.18 SKD-110 simulation */
const { b, sec, flow, cmp, scen, step, mist, gl, chk, tool, take, res, rf, lesson, dur, NOTICE } = require('./h');
const KEYNOTE = { en: 'Metanoia reasoning key. BKN publishes no TKP key. Rankings are our team’s reasoning from the ASN core values and the PermenPAN-RB blueprint; other providers may rank differently. Reviewer agreement is shown on every panel.', id: 'Kunci penalaran Metanoia. BKN tidak menerbitkan kunci TKP. Peringkat adalah penalaran tim kami berdasarkan nilai dasar ASN dan kisi-kisi PermenPAN-RB; peringkat penyedia lain dapat berbeda. Kesepakatan penelaah ditampilkan di setiap panel.' };

const L1215 = lesson({
  n: '12.15', kind: 'interactive', dur: dur(50),
  title: b('TIU at CAT Speed: 35 Items, 72 Seconds Each', 'TIU dengan Kecepatan CAT: 35 Soal, 72 Detik Masing-masing'),
  overview: b('TIU is the SKD section with the hardest threshold relative to its ceiling (config: 80 of 175, sixteen correct out of 35) and the one where time is lost. Its eight sub-types in the config blueprint are the families you have trained: analogy, syllogism, analytic, arithmetic, series, comparison, story and table, figural. This lesson sets the budget per sub-type inside the 72-second average, gives the order in which to take the 35 items, and runs the TIU section practice.', 'TIU adalah bagian SKD dengan ambang tersulit relatif terhadap batas atasnya (konfigurasi: 80 dari 175, enam belas benar dari 35) dan tempat waktu hilang. Delapan sub-tipenya dalam kisi-kisi konfigurasi adalah keluarga yang telah kamu latih: analogi, silogisme, analitis, berhitung, deret, perbandingan, cerita dan tabel, figural. Pelajaran ini menetapkan anggaran per sub-tipe dalam rata-rata 72 detik, memberi urutan mengerjakan 35 soal, dan menjalankan latihan bagian TIU.'),
  objectives: [b('Budget 35 TIU items inside about 42 minutes of a 100-minute test.', 'Menganggarkan 35 soal TIU dalam sekitar 42 menit dari tes 100 menit.'), b('Take the items in strength order using the grid and the doubt flag.', 'Mengerjakan soal berurutan kekuatan memakai kisi dan tanda ragu.'), b('Apply the skip rule at 1.5× budget without leaving blanks.', 'Menerapkan aturan melewati pada 1,5× anggaran tanpa meninggalkan kosong.'), b('Reach sixteen sure answers before spending time on hard items.', 'Mencapai enam belas jawaban pasti sebelum menghabiskan waktu untuk soal sulit.')],
  readFirst: rf('TIU in 42 minutes', 'TIU dalam 42 menit', 'Budget, order, skip, return.', 'Anggaran, urutan, lewati, kembali.', [
    ['The budget', 'Anggaran', [['TWK 20 minutes, TIU 42, TKP 35, 3 spare: checkpoints on the global clock.', 'TWK 20 menit, TIU 42, TKP 35, 3 cadangan: titik periksa pada jam global.'], ['72 seconds per TIU item on average; 40 for analogy, 110 for analytic.', '72 detik per soal TIU rata-rata; 40 untuk analogi, 110 untuk analitis.']]],
    ['Strength order', 'Urutan kekuatan', [['Answer your green sub-types first across the whole section, then amber, then red.', 'Jawab sub-tipe hijaumu dulu di seluruh bagian, lalu kuning, lalu merah.'], ['Sixteen sure answers is the threshold; bank them early.', 'Enam belas jawaban pasti adalah ambangnya; amankan lebih dulu.']]],
    ['Skip and return', 'Lewati dan kembali', [['At 1.5× budget: best option, flag, move on. Never blank.', 'Pada 1,5× anggaran: opsi terbaik, tandai, lanjut. Jangan pernah kosong.'], ['Return to flags with the spare minutes, strongest family first.', 'Kembali ke tanda dengan menit cadangan, keluarga terkuat dulu.']]]
  ]),
  sections: [
    sec('clock', 'The budget inside 100 minutes', 'Anggaran dalam 100 menit', 'One global clock, so the budget is yours to enforce. The Lab’s default plan: TWK 20 minutes (30 items at 40 seconds), TIU 42 minutes (35 items at 72 seconds), TKP 35 minutes (45 items at about 47 seconds), 3 minutes spare for flags. Inside TIU, the 72-second average splits by sub-type: analogy 40, syllogism 55, series 50, arithmetic 60, comparison 55, figural 55, story and table 90, analytic 110 per item (the first item in a set costs the list; the next two are cheap). Write the three section checkpoints on the scrap paper the test centre provides: TWK done by 20:00 elapsed, TIU by 62:00, TKP by 97:00.', 'Satu jam global, jadi anggaran adalah milikmu untuk ditegakkan. Rencana bawaan Lab: TWK 20 menit (30 soal pada 40 detik), TIU 42 menit (35 soal pada 72 detik), TKP 35 menit (45 soal pada sekitar 47 detik), 3 menit cadangan untuk tanda. Di dalam TIU, rata-rata 72 detik terbagi per sub-tipe: analogi 40, silogisme 55, deret 50, berhitung 60, perbandingan 55, figural 55, cerita dan tabel 90, analitis 110 per soal (soal pertama dalam satu set membayar daftarnya; dua berikutnya murah). Tulis tiga titik periksa bagian di kertas coret yang disediakan lokasi tes: TWK selesai pada menit ke-20, TIU pada menit ke-62, TKP pada menit ke-97.'),
    sec('trendUp', 'Strength order with the grid', 'Urutan kekuatan dengan kisi', 'The CAT lets you move among all items, so take TIU in strength order, not number order. First pass: every item in your green sub-types (from the weakness map), answered and left unflagged. Second pass: amber sub-types, answered, flagged if over budget. Third pass: red sub-types, answered with the best option and flagged. The threshold in the config is sixteen correct; most candidates with a green verbal and figural reach sixteen in the first two passes, which turns the red sub-types into bonus rather than risk. The grid shows the three states (answered, flagged, unanswered) at a glance; unanswered must be zero before the TIU checkpoint.', 'CAT membolehkanmu berpindah di antara semua soal, jadi kerjakan TIU berurutan kekuatan, bukan nomor. Putaran pertama: setiap soal di sub-tipe hijaumu (dari peta kelemahan), dijawab dan tidak ditandai. Putaran kedua: sub-tipe kuning, dijawab, ditandai jika melewati anggaran. Putaran ketiga: sub-tipe merah, dijawab dengan opsi terbaik dan ditandai. Ambang di konfigurasi adalah enam belas benar; kebanyakan peserta dengan verbal dan figural hijau mencapai enam belas di dua putaran pertama, yang mengubah sub-tipe merah menjadi bonus alih-alih risiko. Kisi menampilkan tiga keadaan (terjawab, ditandai, belum terjawab) sekilas; belum terjawab harus nol sebelum titik periksa TIU.'),
    sec('flag', 'The skip rule and the return', 'Aturan melewati dan kembali', 'At 1.5× the sub-type budget (60 seconds on an analogy, 165 on an analytic item), stop: choose the best remaining option, press the doubt flag, move on. Blanks score zero and there is no penalty, so a flagged guess is strictly better than a blank. The return happens in the spare three minutes and in whatever TKP leaves over: open flagged items in order of family strength, strongest first, because those resolve fastest. The Lab’s TIU section practice enforces the same rule and reports how many flags you resolved and how many of them changed from wrong to right.', 'Pada 1,5× anggaran sub-tipe (60 detik untuk analogi, 165 untuk soal analitis), berhenti: pilih opsi tersisa terbaik, tekan tanda ragu, lanjut. Kosong bernilai nol dan tidak ada penalti, jadi tebakan bertanda jauh lebih baik daripada kosong. Kembalinya terjadi pada tiga menit cadangan dan sisa apa pun dari TKP: buka soal bertanda berurutan kekuatan keluarga, terkuat dulu, karena itu paling cepat selesai. Latihan bagian TIU Lab memberlakukan aturan yang sama dan melaporkan berapa tanda yang kamu selesaikan dan berapa yang berubah dari salah ke benar.'),
    sec('layers', 'Sub-types in the config blueprint', 'Sub-tipe dalam kisi-kisi konfigurasi', 'The Lab’s TIU blueprint (config; verify against the current PermenPAN-RB): analogy 4, syllogism 5, analytic 4, arithmetic 5, series 5, comparison 4, story and table 3, figural 5. Every one maps to a Module 7 or Track A lesson; nothing is new. What is new is only the clock and the order. Candidates who are strong in the verbal sub-types (analogy, syllogism) and figural can bank fourteen items in about twelve minutes, leaving thirty minutes for the numerical and analytic twenty-one.', 'Kisi-kisi TIU Lab (konfigurasi; verifikasi terhadap PermenPAN-RB yang berlaku): analogi 4, silogisme 5, analitis 4, berhitung 5, deret 5, perbandingan 4, cerita dan tabel 3, figural 5. Setiap sub-tipe memetakan ke pelajaran Modul 7 atau Jalur A; tidak ada yang baru. Yang baru hanya jam dan urutannya. Peserta yang kuat di sub-tipe verbal (analogi, silogisme) dan figural bisa mengamankan empat belas soal dalam sekitar dua belas menit, menyisakan tiga puluh menit untuk dua puluh satu soal numerik dan analitis.')
  ],
  diagram: flow('Exhibit 1: Three passes through TIU', 'Peraga 1: Tiga putaran melewati TIU', 'Bank the threshold before you spend on hard items', 'Amankan ambang sebelum menghabiskan untuk soal sulit', [
    ['check', 'Pass 1 · green', 'Putaran 1 · hijau', 'Your strongest sub-types, answered, unflagged.', 'Sub-tipe terkuatmu, dijawab, tanpa tanda.'],
    ['flag', 'Pass 2 · amber', 'Putaran 2 · kuning', 'Answered; flagged if over budget.', 'Dijawab; ditandai jika melewati anggaran.'],
    ['x', 'Pass 3 · red', 'Putaran 3 · merah', 'Best option, flagged; never blank.', 'Opsi terbaik, ditandai; jangan pernah kosong.'],
    ['refresh', 'Return', 'Kembali', 'Spare minutes on flags, strongest family first.', 'Menit cadangan untuk tanda, keluarga terkuat dulu.']
  ]),
  compare: [cmp('Two TIU sittings', 'Dua kali duduk TIU', 'Thirty-five items, 42 minutes, same candidate.', 'Tiga puluh lima soal, 42 menit, peserta yang sama.', 'Number order. Item 3 is an analytic set that takes seven minutes. Items 28 to 35 are answered in the last ninety seconds at random. TIU 70: below the bar.', 'Urutan nomor. Soal 3 adalah set analitis yang memakan tujuh menit. Soal 28 sampai 35 dijawab dalam sembilan puluh detik terakhir secara acak. TIU 70: di bawah batas.', 'Strength order. Analogy, syllogism and figural banked in eleven minutes: fourteen sure. Series and arithmetic next. The analytic set last, with its list. TIU 100.', 'Urutan kekuatan. Analogi, silogisme, dan figural diamankan dalam sebelas menit: empat belas pasti. Deret dan berhitung berikutnya. Set analitis terakhir, dengan daftarnya. TIU 100.', 'Same ability, same items; the order moved thirty points.', 'Kemampuan yang sama, soal yang sama; urutan menggerakkan tiga puluh poin.')],
  scenario: scen('clock', 'In focus: the checkpoint', 'Sorotan: titik periksa', [['A candidate wrote “62:00” on the scrap paper and, at 61 minutes with three TIU items unanswered, chose the best option on each, flagged them and moved to TKP. She finished TKP at 95 minutes and resolved two of the three flags. Without the checkpoint she would have been at TIU item 33 at minute 70 and started TKP with 30 minutes for 45 items.', 'Seorang peserta menulis “62:00” di kertas coret dan, pada menit ke-61 dengan tiga soal TIU belum terjawab, memilih opsi terbaik untuk masing-masing, menandainya, dan pindah ke TKP. Ia menyelesaikan TKP pada menit ke-95 dan menyelesaikan dua dari tiga tanda. Tanpa titik periksa ia akan berada di soal TIU 33 pada menit ke-70 dan memulai TKP dengan 30 menit untuk 45 soal.']]),
  steps: [
    step('Drill 1 · Budget card', 'Latihan 1 · Kartu anggaran', 'Write the three section checkpoints and the eight TIU sub-type budgets on a card. Memorise the checkpoints; the card stays home.', 'Tulis tiga titik periksa bagian dan delapan anggaran sub-tipe TIU di kartu. Hafalkan titik periksanya; kartu tetap di rumah.', 'Test centres provide scrap paper but not your card; the checkpoints must be in your head.', 'Lokasi tes menyediakan kertas coret tetapi bukan kartumu; titik periksa harus ada di kepala.'),
    step('Drill 2 · TIU section practice in strength order', 'Latihan 2 · Latihan bagian TIU berurutan kekuatan', 'Thirty-five items, 42 minutes, grid and flags on. Take three passes by colour from your weakness map.', 'Tiga puluh lima soal, 42 menit, kisi dan tanda menyala. Lakukan tiga putaran berdasarkan warna dari peta kelemahanmu.', 'Read the report’s “sure by minute” line: the minute at which you reached sixteen unflagged answers.', 'Baca baris “pasti per menit” di laporan: menit saat kamu mencapai enam belas jawaban tanpa tanda.'),
    step('Drill 3 · Flag resolution', 'Latihan 3 · Penyelesaian tanda', 'Repeat the section practice. In the return, log which flags changed from wrong to right and in which family.', 'Ulangi latihan bagian. Saat kembali, catat tanda mana yang berubah dari salah ke benar dan di keluarga mana.', 'If most resolved flags are in one family, that family’s budget is too tight; add ten seconds there and take it from the greenest.', 'Jika kebanyakan tanda yang selesai ada di satu keluarga, anggaran keluarga itu terlalu ketat; tambahkan sepuluh detik di sana dan ambil dari yang paling hijau.')
  ],
  mistakes: mist([['Number order', 'Urutan nomor', 'Strength order with the grid; bank sixteen early.', 'Urutan kekuatan dengan kisi; amankan enam belas lebih awal.'], ['No checkpoint', 'Tanpa titik periksa', 'One clock; the checkpoints are yours.', 'Satu jam; titik periksa adalah milikmu.'], ['Blanks “for later”', 'Kosong “untuk nanti”', 'Best option plus flag; a blank is a certain zero.', 'Opsi terbaik plus tanda; kosong adalah nol pasti.'], ['Starting with the analytic set', 'Mulai dengan set analitis', 'It costs the most per item; take it last with its list.', 'Paling mahal per soal; kerjakan terakhir dengan daftarnya.']]),
  glossary: gl([['Budget', 'Anggaran', 'Seconds per item per sub-type, summing to the section checkpoint.', 'Detik per soal per sub-tipe, berjumlah ke titik periksa bagian.'], ['Checkpoint', 'Titik periksa', 'Elapsed minute by which a section must be finished (20, 62, 97).', 'Menit berjalan saat satu bagian harus selesai (20, 62, 97).'], ['Strength order', 'Urutan kekuatan', 'Green sub-types first, then amber, then red.', 'Sub-tipe hijau dulu, lalu kuning, lalu merah.'], ['Sure answers', 'Jawaban pasti', 'Answered and unflagged.', 'Dijawab dan tidak ditandai.'], ['Return', 'Kembali', 'Spare minutes spent on flagged items, strongest family first.', 'Menit cadangan untuk soal bertanda, keluarga terkuat dulu.'], ['Blueprint', 'Kisi-kisi', 'Items per sub-type in the config (verify per cycle).', 'Jumlah soal per sub-tipe di konfigurasi (verifikasi per siklus).']]),
  checks: [
    chk('With TIU’s threshold at 80 (config), the number of correct answers needed is …', 'Dengan ambang TIU 80 (konfigurasi), jumlah jawaban benar yang diperlukan adalah …', [['twenty', 'dua puluh'], ['sixteen', 'enam belas'], ['eighteen', 'delapan belas'], ['thirty-five', 'tiga puluh lima']], 1, '80 ÷ 5 = 16.', '80 ÷ 5 = 16.'),
    chk('At 1.5× the budget on a TIU item, you should …', 'Pada 1,5× anggaran untuk soal TIU, kamu sebaiknya …', [['leave it blank for later', 'biarkan kosong untuk nanti'], ['choose the best option, flag it, move on', 'pilih opsi terbaik, tandai, lanjut'], ['finish it whatever it takes', 'selesaikan apa pun biayanya'], ['skip to TKP', 'lompat ke TKP']], 1, 'No penalty; a flagged guess beats a blank.', 'Tanpa penalti; tebakan bertanda mengalahkan kosong.'),
    chk('The TIU checkpoint in the Lab’s default plan is at elapsed minute …', 'Titik periksa TIU dalam rencana bawaan Lab ada pada menit ke-…', [['42', '42'], ['62', '62'], ['80', '80'], ['100', '100']], 1, 'TWK by 20, TIU by 62, TKP by 97, three spare.', 'TWK pada 20, TIU pada 62, TKP pada 97, tiga cadangan.')
  ],
  tool: tool('section:tiu', 'TIU section practice', 'Latihan bagian TIU', 'Thirty-five original items in the config blueprint, 42 minutes, grid, doubt flag, skip prompts at 1.5× budget; report by sub-type with “sure by minute” and flag resolution. Metanoia practice form in an SKD-like format.', 'Tiga puluh lima soal asli dalam kisi-kisi konfigurasi, 42 menit, kisi, tanda ragu, ajakan melewati pada 1,5× anggaran; laporan per sub-tipe dengan “pasti per menit” dan penyelesaian tanda. Formulir latihan Metanoia dalam format mirip SKD.'),
  takeaways: take([['Checkpoints 20, 62, 97 on one global clock.', 'Titik periksa 20, 62, 97 pada satu jam global.'], ['Strength order; sixteen sure answers before any hard item.', 'Urutan kekuatan; enam belas jawaban pasti sebelum soal sulit apa pun.'], ['Best option, flag, move on; never blank.', 'Opsi terbaik, tandai, lanjut; jangan pernah kosong.']]),
  resources: res('Blueprint source', 'Sumber kisi-kisi', 'Verify per cycle.', 'Verifikasi per siklus.', [['PermenPAN-RB blueprint', 'Kisi-kisi PermenPAN-RB', 'TIU sub-topics.', 'Sub-topik TIU.', [['The sub-type counts are the Lab config’s reading of the 2024 blueprint (verbal: analogi, silogisme, analitis; numerik: berhitung, deret, perbandingan kuantitatif, soal cerita; figural: analogi, ketidaksamaan, serial). Check the current regulation.', 'Jumlah sub-tipe adalah pembacaan konfigurasi Lab atas kisi-kisi 2024 (verbal: analogi, silogisme, analitis; numerik: berhitung, deret, perbandingan kuantitatif, soal cerita; figural: analogi, ketidaksamaan, serial). Cek peraturan yang berlaku.'], [NOTICE.en, NOTICE.id]]]])
});

const L1216 = lesson({
  n: '12.16', kind: 'reading', dur: dur(45),
  title: b('TKP I: Six Dimensions and Ranked Scoring', 'TKP I: Enam Dimensi dan Skor Berjenjang'),
  overview: b('TKP carries 225 of the SKD’s 550 points and the highest threshold (config: 166), breaks ties first, and is answered by judgement rather than knowledge. Its six dimensions in the blueprint are public service, networking, socio-cultural, information and communication technology, professionalism and anti-radicalism. Every option scores 1 to 5; there is no official key, so the Lab publishes its reasoning with a ladder on every item. This lesson gives the six dimensions with what each rewards, the ladder, the honesty block, and the three traps.', 'TKP membawa 225 dari 550 poin SKD dan ambang tertinggi (konfigurasi: 166), menentukan nilai sama lebih dulu, dan dijawab dengan pertimbangan alih-alih pengetahuan. Enam dimensinya dalam kisi-kisi adalah pelayanan publik, jejaring kerja, sosial budaya, teknologi informasi dan komunikasi, profesionalisme, dan anti-radikalisme. Setiap opsi bernilai 1 sampai 5; tidak ada kunci resmi, sehingga Lab menerbitkan penalarannya dengan tangga pada setiap soal. Pelajaran ini memberi enam dimensi beserta apa yang dihargai masing-masing, tangganya, blok kejujuran, dan tiga jebakan.'),
  objectives: [b('Name the six TKP dimensions and what each rewards.', 'Menyebutkan enam dimensi TKP dan apa yang dihargai masing-masing.'), b('Rank five options with the ladder and compute the item score.', 'Mengurutkan lima opsi dengan tangga dan menghitung skor soal.'), b('Explain why no official key exists and how to read Metanoia’s reasoning key.', 'Menjelaskan mengapa tidak ada kunci resmi dan cara membaca kunci penalaran Metanoia.'), b('Avoid the heroic, the loyal-to-a-person and the second-best traps.', 'Menghindari jebakan heroik, setia-pada-orang, dan terbaik kedua.')],
  readFirst: rf('TKP in four lines', 'TKP dalam empat baris', 'Six dimensions, ranked, no official key, one ladder.', 'Enam dimensi, berjenjang, tanpa kunci resmi, satu tangga.', [
    ['Six dimensions', 'Enam dimensi', [['Public service, networking, socio-cultural, ICT, professionalism, anti-radicalism.', 'Pelayanan publik, jejaring kerja, sosial budaya, TIK, profesionalisme, anti-radikalisme.'], ['Name the dimension first; it tells you what the best option does.', 'Sebutkan dimensinya dulu; itu memberi tahu apa yang dilakukan opsi terbaik.']]],
    ['Every option scores', 'Setiap opsi bernilai', [['5 to 1; blank 0; 45 items; threshold 166 means a mean above 3.7.', '5 sampai 1; kosong 0; 45 soal; ambang 166 berarti rata-rata di atas 3,7.'], ['All 4s gives 180; the bar is passed by avoiding 2s and 1s, then by turning 4s into 5s.', 'Semua 4 memberi 180; batas dilewati dengan menghindari 2 dan 1, lalu mengubah 4 menjadi 5.']]],
    ['No official key', 'Tanpa kunci resmi', [['BKN publishes none; the Lab shows its reasoning and the reviewer status.', 'BKN tidak menerbitkan; Lab menampilkan penalaran dan status penelaahnya.'], ['Disagree where you must, but know the ladder you disagree with.', 'Tidak sepakat bila perlu, tetapi kenali tangga yang kamu tidak sepakati.']]]
  ]),
  sections: [
    sec('heart', 'The six dimensions', 'Enam dimensi', '<b>Public service</b> (pelayanan publik) rewards serving the citizen now, within procedure, and fixing the source of the problem. <b>Networking</b> (jejaring kerja) rewards building and keeping working relationships across units and institutions, separating personal conflict from cooperation. <b>Socio-cultural</b> (sosial budaya) rewards adapting to and respecting difference, inclusion, and the bahasa negara alongside local languages. <b>ICT</b> (teknologi informasi dan komunikasi) rewards safe, lawful, data-protecting use of technology and helping others adopt it. <b>Professionalism</b> rewards responsibility for your own work, honest error handling, priorities communicated, feedback taken. <b>Anti-radicalism</b> rewards dialogue, non-dissemination, protection of the targeted and escalation when violence is urged. The config blueprint (verify) gives them 9, 7, 7, 6, 8 and 8 items.', '<b>Pelayanan publik</b> menghargai melayani warga sekarang, dalam prosedur, dan membereskan sumber masalah. <b>Jejaring kerja</b> menghargai membangun dan menjaga hubungan kerja lintas unit dan lembaga, memisahkan konflik pribadi dari kerja sama. <b>Sosial budaya</b> menghargai menyesuaikan diri dan menghormati perbedaan, inklusi, dan bahasa negara berdampingan dengan bahasa daerah. <b>TIK</b> menghargai pemakaian teknologi yang aman, sah, melindungi data, dan membantu orang lain mengadopsinya. <b>Profesionalisme</b> menghargai tanggung jawab atas kerja sendiri, penanganan kesalahan yang jujur, prioritas yang dikomunikasikan, umpan balik yang diterima. <b>Anti-radikalisme</b> menghargai dialog, tidak menyebarkan, melindungi yang disasar, dan eskalasi saat kekerasan diserukan. Kisi-kisi konfigurasi (verifikasi) memberi 9, 7, 7, 6, 8, dan 8 soal.'),
    sec('chart', 'Ranked scoring, with the arithmetic', 'Skor berjenjang, dengan aritmetikanya', 'Each TKP item scores the option you chose from 1 to 5, blank 0. Forty-five items, maximum 225, threshold 166 in the config, so a mean of 3.69 per item. Three consequences. First, blanks are catastrophic: ten blanks cost at least ten points and typically thirty. Second, avoiding 1s and 2s matters more than finding 5s: a candidate who never scores below 3 is already at 135 and needs only sixteen 5s. Third, the “second-best habit” decides the margin: all 4s is 180 and passes; the difference between 180 and 210 is thirty 4s becoming 5s, which the ladder teaches in one sitting.', 'Setiap soal TKP menilai opsi yang kamu pilih dari 1 sampai 5, kosong 0. Empat puluh lima soal, maksimal 225, ambang 166 di konfigurasi, jadi rata-rata 3,69 per soal. Tiga akibat. Pertama, kosong itu fatal: sepuluh kosong merugikan setidaknya sepuluh poin dan biasanya tiga puluh. Kedua, menghindari 1 dan 2 lebih penting daripada menemukan 5: peserta yang tidak pernah di bawah 3 sudah di 135 dan hanya perlu enam belas nilai 5. Ketiga, “kebiasaan terbaik kedua” menentukan margin: semua 4 adalah 180 dan lulus; selisih antara 180 dan 210 adalah tiga puluh nilai 4 yang menjadi 5, yang diajarkan tangga dalam satu kali duduk.'),
    sec('trendUp', 'The ladder', 'Tangga', 'The Lab keys every TKP item with the same ladder it uses for AKHLAK (Lesson 12.8): <b>5</b> proactive, within your authority, fixes the root cause, keeps people and procedure intact; <b>4</b> good but partial or passive; <b>3</b> neutral or deferring; <b>2</b> avoiding; <b>1</b> harmful or rule-breaking. Each review screen shows the five options in ladder order with the reason for each step, the trap each distractor represents, and the reviewer status. Rank from the ends: the 1 is usually obvious (gossip, retaliation, the bribe); the 5 is the option that does two things (acts now and fixes the system); the 4 is the one that does one of them.', 'Lab mengunci setiap soal TKP dengan tangga yang sama dengan AKHLAK (Pelajaran 12.8): <b>5</b> proaktif, dalam kewenanganmu, membereskan akar masalah, menjaga orang dan prosedur utuh; <b>4</b> baik tetapi sebagian atau pasif; <b>3</b> netral atau menyerahkan; <b>2</b> menghindar; <b>1</b> merugikan atau melanggar aturan. Setiap layar tinjauan menampilkan lima opsi dalam urutan tangga dengan alasan tiap anak tangga, jebakan yang diwakili tiap pengecoh, dan status penelaah. Urutkan dari ujung: 1 biasanya jelas (gunjing, balas dendam, suap); 5 adalah opsi yang melakukan dua hal (bertindak sekarang dan memperbaiki sistem); 4 adalah yang melakukan salah satunya.'),
    sec('shieldTick', 'The honesty block', 'Blok kejujuran', 'BKN does not publish a TKP key, and the Lab will not pretend otherwise. Every TKP panel carries the notice that its ranking is Metanoia’s reasoning from the ASN core values and the PermenPAN-RB blueprint, that other providers may rank differently, and the reviewer status of the item (the Lab’s items are a content-team draft awaiting a three-reviewer panel, and say so). Use the keys to learn the ladder, not to memorise answers: the real items are different, and the ladder is what transfers. Where you disagree with a key, write why in the Dossier; a reasoned disagreement is the best possible preparation for an item you have never seen.', 'BKN tidak menerbitkan kunci TKP, dan Lab tidak akan berpura-pura sebaliknya. Setiap panel TKP memuat pemberitahuan bahwa peringkatnya adalah penalaran Metanoia dari nilai dasar ASN dan kisi-kisi PermenPAN-RB, bahwa penyedia lain dapat mengurutkan berbeda, dan status penelaah soal tersebut (soal Lab adalah draf tim konten yang menunggu panel tiga penelaah, dan mengatakannya). Pakai kuncinya untuk mempelajari tangga, bukan menghafal jawaban: soal sesungguhnya berbeda, dan tangga adalah yang berpindah. Jika kamu tidak sepakat dengan kunci, tulis alasannya di Dossier; ketidaksepakatan yang bernalar adalah persiapan terbaik untuk soal yang belum pernah kamu lihat.'),
    sec('x', 'Three traps', 'Tiga jebakan', 'The <b>heroic</b> option overrides authority (changes the procedure yourself, releases data to a partner, fills a vacant counter without telling anyone) and scores 2 or 3. The <b>loyal-to-a-person</b> option covers a manager or colleague and scores 1. The <b>second-best</b> option informs, helps once, or waits, and scores 4. A fourth, specific to public service: the <b>procedure-only</b> option that follows the letter of the rule while the citizen leaves unserved scores 3. The explanations tag each; your trap tags accumulate and the Lab reports which trap costs you most.', 'Opsi <b>heroik</b> melangkahi kewenangan (mengubah prosedur sendiri, membuka data ke mitra, mengisi loket kosong tanpa memberi tahu siapa pun) dan bernilai 2 atau 3. Opsi <b>setia-pada-orang</b> menutupi manajer atau rekan dan bernilai 1. Opsi <b>terbaik kedua</b> memberi tahu, membantu sekali, atau menunggu, dan bernilai 4. Yang keempat, khas pelayanan publik: opsi <b>prosedur-saja</b> yang mengikuti bunyi aturan sementara warga pergi tanpa dilayani bernilai 3. Penjelasan menandai masing-masing; tanda jebakanmu terkumpul dan Lab melaporkan jebakan mana yang paling merugikanmu.')
  ],
  diagram: flow('Exhibit 1: Six dimensions', 'Peraga 1: Enam dimensi', 'What the best option does in each', 'Apa yang dilakukan opsi terbaik di masing-masing', [
    ['users', 'Public service', 'Pelayanan publik', 'Serve now, within procedure, fix the source.', 'Layani sekarang, dalam prosedur, bereskan sumbernya.'],
    ['handshake', 'Networking', 'Jejaring kerja', 'Keep cooperation above conflict; coordinate.', 'Jaga kerja sama di atas konflik; koordinasi.'],
    ['globe', 'Socio-cultural', 'Sosial budaya', 'Respect difference; include; adapt.', 'Hormati perbedaan; libatkan; sesuaikan.'],
    ['laptop', 'ICT', 'TIK', 'Safe, lawful, data-protecting; help others adopt.', 'Aman, sah, melindungi data; bantu orang lain mengadopsi.'],
    ['briefcase', 'Professionalism', 'Profesionalisme', 'Own your work; honest errors; communicated priorities.', 'Tanggung jawab kerja; kesalahan jujur; prioritas dikomunikasikan.'],
    ['shield', 'Anti-radicalism', 'Anti-radikalisme', 'Dialogue, no spreading, protect, escalate on violence.', 'Dialog, tidak menyebar, lindungi, eskalasi saat kekerasan.']
  ]),
  compare: [cmp('Two rankings of the counter', 'Dua peringkat untuk loket', 'An elderly citizen arrives five minutes before closing with incomplete papers.', 'Warga lanjut usia datang lima menit sebelum tutup dengan berkas tidak lengkap.', 'Chooses “explain what is missing and ask her to return tomorrow”: polite, procedural, nothing done today. A 3.', 'Memilih “jelaskan yang kurang dan minta ia kembali besok”: sopan, prosedural, tidak ada yang selesai hari ini. Nilai 3.', 'Chooses “check the papers, explain the gap, and complete today whatever can be completed”: serves now, within authority, and the gap is named. A 5.', 'Memilih “periksa berkas, jelaskan kekurangannya, dan selesaikan hari ini apa yang bisa diselesaikan”: melayani sekarang, dalam kewenangan, dan kekurangannya disebut. Nilai 5.', 'Public service rewards the option that does something for the citizen today without breaking procedure.', 'Pelayanan publik menghargai opsi yang melakukan sesuatu untuk warga hari ini tanpa melanggar prosedur.')],
  scenario: scen('heart', 'In focus: the mean', 'Sorotan: rata-rata', [['Two candidates, same TKP set. One had eight 5s, thirty 4s, seven 3s: 181. The other had twenty 5s, ten 4s, ten 3s, five 1s: 175. The first had never chosen a harmful option; the second had five, each a “cover for the colleague” pick. Avoiding 1s and 2s is the floor; the ceiling is the 4s.', 'Dua peserta, set TKP yang sama. Satu punya delapan nilai 5, tiga puluh nilai 4, tujuh nilai 3: 181. Yang lain dua puluh nilai 5, sepuluh nilai 4, sepuluh nilai 3, lima nilai 1: 175. Yang pertama tidak pernah memilih opsi merugikan; yang kedua lima kali, masing-masing pilihan “tutupi rekan”. Menghindari 1 dan 2 adalah lantainya; langit-langitnya adalah nilai 4.']]),
  steps: [
    step('Drill 1 · Name the dimension', 'Latihan 1 · Sebutkan dimensinya', 'Twelve TKP items, two per dimension. Before the options, write the dimension and what its best option must do.', 'Dua belas soal TKP, dua per dimensi. Sebelum opsi, tulis dimensinya dan apa yang harus dilakukan opsi terbaiknya.', 'The dimension predicts the 5 more reliably than the scenario’s drama does.', 'Dimensi meramalkan nilai 5 lebih andal daripada drama skenarionya.'),
    step('Drill 2 · Rank from the ends', 'Latihan 2 · Urutkan dari ujung', 'Twelve more. Mark the 1 and the 5 first, then the 4, then the rest. Compare with the ladder and read the reason for every step you disagree with.', 'Dua belas lagi. Tandai 1 dan 5 dulu, lalu 4, lalu sisanya. Bandingkan dengan tangga dan baca alasan tiap anak tangga yang kamu tidak sepakati.', 'Record your disagreements with reasons in the Dossier; they are not errors unless the reason is “it felt safer”.', 'Catat ketidaksepakatanmu beserta alasannya di Dossier; itu bukan kesalahan kecuali alasannya “terasa lebih aman”.'),
    step('Drill 3 · Find your trap', 'Latihan 3 · Temukan jebakanmu', 'Read the trap-tag summary in the Lab after twenty-four items. Write the trap that costs you most and the one sentence that defeats it.', 'Baca ringkasan tanda jebakan di Lab setelah dua puluh empat soal. Tulis jebakan yang paling merugikanmu dan satu kalimat yang mengalahkannya.', 'Heroic: “is this within my authority?”. Loyal-to-person: “loyal to whom?”. Second-best: “does this fix the cause?”.', 'Heroik: “apakah ini dalam kewenanganku?”. Setia-pada-orang: “setia kepada siapa?”. Terbaik kedua: “apakah ini membereskan sebabnya?”.')
  ],
  mistakes: mist([['Leaving TKP items blank', 'Membiarkan soal TKP kosong', 'Every option scores at least 1; blank is 0.', 'Setiap opsi bernilai setidaknya 1; kosong 0.'], ['Memorising keys', 'Menghafal kunci', 'Learn the ladder; the real items differ.', 'Pelajari tangganya; soal sesungguhnya berbeda.'], ['Choosing the dramatic option', 'Memilih opsi dramatis', 'Authority and procedure are part of the ladder.', 'Kewenangan dan prosedur adalah bagian tangga.'], ['Treating “inform the boss” as the best', 'Menganggap “beri tahu atasan” yang terbaik', 'It is usually a 4 or 3; the 5 also acts.', 'Biasanya 4 atau 3; nilai 5 juga bertindak.']]),
  glossary: gl([['TKP', 'TKP', 'Tes Karakteristik Pribadi: 45 ranked situational items.', 'Tes Karakteristik Pribadi: 45 soal situasional berjenjang.'], ['Dimension', 'Dimensi', 'One of six blueprint areas each item belongs to.', 'Satu dari enam area kisi-kisi tempat tiap soal berada.'], ['Ladder', 'Tangga', 'The five-step reasoning from 5 (fixes) to 1 (harms).', 'Penalaran lima anak tangga dari 5 (membereskan) sampai 1 (merugikan).'], ['Reasoning key', 'Kunci penalaran', 'Metanoia’s ranking with reasons and reviewer status; no official key exists.', 'Peringkat Metanoia dengan alasan dan status penelaah; tidak ada kunci resmi.'], ['Second-best share', 'Porsi terbaik kedua', 'Proportion of picks that scored 4.', 'Proporsi pilihan yang bernilai 4.'], ['Procedure-only option', 'Opsi prosedur-saja', 'Follows the rule’s letter while the citizen stays unserved; a 3.', 'Mengikuti bunyi aturan sementara warga tak terlayani; nilai 3.']]),
  checks: [
    chk('On TKP, a candidate who scores 4 on every one of 45 items totals …', 'Pada TKP, peserta yang bernilai 4 pada setiap dari 45 soal mendapat total …', [['225', '225'], ['180', '180'], ['166', '166'], ['135', '135']], 1, '45 × 4 = 180, above the config threshold of 166.', '45 × 4 = 180, di atas ambang konfigurasi 166.'),
    chk('The official TKP key is published by …', 'Kunci TKP resmi diterbitkan oleh …', [['BKN each cycle', 'BKN tiap siklus'], ['nobody; the Lab shows its own reasoning and says so', 'tidak ada; Lab menampilkan penalarannya sendiri dan mengatakannya'], ['the test centre', 'lokasi tes'], ['the ministry on request', 'kementerian bila diminta']], 1, 'No official key; the Lab’s notice appears on every panel.', 'Tidak ada kunci resmi; pemberitahuan Lab muncul di setiap panel.'),
    chk('“Inform the manager and wait for instructions” is usually ranked …', '“Beri tahu manajer dan tunggu arahan” biasanya diperingkat …', [['5: it respects authority', '5: menghormati kewenangan'], ['3 or 4: it defers or helps without acting', '3 atau 4: menyerahkan atau membantu tanpa bertindak'], ['1: it is cowardly', '1: pengecut'], ['0: it is a blank', '0: kosong']], 1, 'The 5 acts within authority and fixes; deferring alone is lower.', 'Nilai 5 bertindak dalam kewenangan dan membereskan; menyerahkan saja lebih rendah.')
  ],
  tool: tool('drill:tkp', 'TKP drills with ranked scoring', 'Latihan TKP dengan skor berjenjang', 'Fifty-four original scenarios across the six dimensions, every option scored, the ladder reason and trap tag on every review, the honesty notice on every panel, and the second-best share in the report.', 'Lima puluh empat skenario asli dari enam dimensi, setiap opsi dinilai, alasan tangga dan tanda jebakan di setiap tinjauan, pemberitahuan kejujuran di setiap panel, dan porsi terbaik kedua di laporan.'),
  takeaways: take([['Six dimensions; name it first.', 'Enam dimensi; sebutkan dulu.'], ['Never blank; avoid 1s and 2s first, then turn 4s into 5s.', 'Jangan pernah kosong; hindari 1 dan 2 dulu, lalu ubah 4 menjadi 5.'], ['No official key; learn the ladder, disagree with reasons.', 'Tanpa kunci resmi; pelajari tangganya, tidak sepakat dengan alasan.']]),
  resources: res('Honesty block', 'Blok kejujuran', 'Printed on every TKP panel.', 'Dicetak di setiap panel TKP.', [['The notice', 'Pemberitahuan', 'Verbatim.', 'Apa adanya.', [[KEYNOTE.en, KEYNOTE.id], [NOTICE.en, NOTICE.id]]]])
});

const L1217 = lesson({
  n: '12.17', kind: 'interactive', dur: dur(50),
  title: b('TKP II: Dimension Practice and the Second-Best Habit', 'TKP II: Latihan per Dimensi dan Kebiasaan Terbaik Kedua'),
  overview: b('With the ladder learned, TKP improves by dimension. This lesson runs the six dimensions one at a time, reads the dimension profile (your mean per dimension out of 5), targets the second-best share, and adds the pacing layer: 45 items in 35 minutes with the judgement-mode transition from TIU. It ends with the TKP section practice.', 'Setelah tangga dipelajari, TKP membaik per dimensi. Pelajaran ini menjalankan enam dimensi satu per satu, membaca profil dimensi (rata-ratamu per dimensi dari 5), menyasar porsi terbaik kedua, dan menambahkan lapisan tempo: 45 soal dalam 35 menit dengan peralihan mode pertimbangan dari TIU. Ditutup dengan latihan bagian TKP.'),
  objectives: [b('Read a dimension profile and pick the dimension to drill.', 'Membaca profil dimensi dan memilih dimensi untuk dilatih.'), b('Reduce the second-best share below 30%.', 'Menurunkan porsi terbaik kedua di bawah 30%.'), b('Answer 45 TKP items in 35 minutes without rushing the last ten.', 'Menjawab 45 soal TKP dalam 35 menit tanpa terburu-buru pada sepuluh terakhir.'), b('Switch from computation to judgement at the TIU to TKP boundary.', 'Beralih dari perhitungan ke pertimbangan pada batas TIU ke TKP.')],
  readFirst: rf('TKP by dimension', 'TKP per dimensi', 'Profile, second-best, pace.', 'Profil, terbaik kedua, tempo.', [
    ['The dimension profile', 'Profil dimensi', [['Mean score per dimension out of 5; the lowest is tomorrow’s drill.', 'Skor rata-rata per dimensi dari 5; yang terendah adalah latihan besok.'], ['A dimension under 3.5 is where 1s and 2s hide.', 'Dimensi di bawah 3,5 adalah tempat 1 dan 2 bersembunyi.']]],
    ['The second-best habit', 'Kebiasaan terbaik kedua', [['Share of picks scoring 4; target under 30%.', 'Porsi pilihan bernilai 4; target di bawah 30%.'], ['Ask “does this fix the cause?” before confirming.', 'Tanyakan “apakah ini membereskan sebabnya?” sebelum mengonfirmasi.']]],
    ['Pace', 'Tempo', [['45 items in 35 minutes: 47 seconds each; read once, name the dimension, rank from the ends.', '45 soal dalam 35 menit: 47 detik masing-masing; baca sekali, sebutkan dimensi, urutkan dari ujung.'], ['The last ten items are where rushed 2s appear.', 'Sepuluh soal terakhir adalah tempat nilai 2 yang terburu-buru muncul.']]]
  ]),
  sections: [
    sec('chart', 'The dimension profile', 'Profil dimensi', 'After every TKP set the Lab shows six bars: your mean score per dimension out of 5. Read it like a weakness map: a dimension under 3.5 contains 1s and 2s, which means a trap (heroic, loyal-to-person, procedure-only) is firing there; a dimension between 3.5 and 4.2 is the second-best habit; above 4.2 is green. Drill the lowest dimension untimed with the ladder reason on every item until its mean passes 4; then the next. Most candidates have one dimension that lags by a full point, usually public service (the procedure-only trap) or networking (the conflict trap).', 'Setelah setiap set TKP, Lab menampilkan enam batang: skor rata-ratamu per dimensi dari 5. Bacalah seperti peta kelemahan: dimensi di bawah 3,5 memuat nilai 1 dan 2, yang berarti satu jebakan (heroik, setia-pada-orang, prosedur-saja) bekerja di sana; dimensi antara 3,5 dan 4,2 adalah kebiasaan terbaik kedua; di atas 4,2 hijau. Latih dimensi terendah tanpa batas waktu dengan alasan tangga pada tiap soal sampai rata-ratanya melewati 4; lalu berikutnya. Kebanyakan peserta punya satu dimensi yang tertinggal satu poin penuh, biasanya pelayanan publik (jebakan prosedur-saja) atau jejaring kerja (jebakan konflik).'),
    sec('target', 'Cutting the second-best share', 'Memangkas porsi terbaik kedua', 'A 4 is never wrong, which is why it is hard to unlearn. The one question that converts 4s into 5s: “does this option fix the cause, or only the symptom?”. The 5 usually does two things in one sentence (act now and repair the system; serve this citizen and report the broken form; decline the gift and give the timeline). When two options both act, the 5 is the one that also prevents recurrence or protects the next person. Practise with the Lab’s “4 or 5?” drill, which shows only the two top options of each scenario and asks which is which; twenty items of that and the share drops.', 'Nilai 4 tidak pernah salah, itulah mengapa sulit dilepaskan. Satu pertanyaan yang mengubah 4 menjadi 5: “apakah opsi ini membereskan sebabnya, atau hanya gejalanya?”. Nilai 5 biasanya melakukan dua hal dalam satu kalimat (bertindak sekarang dan memperbaiki sistem; melayani warga ini dan melaporkan formulir yang rusak; menolak hadiah dan memberi jadwal). Ketika dua opsi sama-sama bertindak, 5 adalah yang juga mencegah pengulangan atau melindungi orang berikutnya. Berlatihlah dengan latihan “4 atau 5?” Lab, yang hanya menampilkan dua opsi teratas tiap skenario dan menanyakan mana yang mana; dua puluh soal itu dan porsinya turun.'),
    sec('clock', 'Pace and the last ten', 'Tempo dan sepuluh terakhir', 'TKP is read-heavy: 45 scenarios of three or four lines each. At 47 seconds per item, the method is read once (do not reread), name the dimension, find the 1 and the 5, confirm. Candidates who reach TKP late answer the last ten in under fifteen seconds each and collect 2s there; the Lab’s section practice reports your score on items 36 to 45 separately so the pattern is visible. If the TIU checkpoint slipped, do not compensate by racing TKP: a 3 chosen calmly beats a 2 chosen fast, and the flagged TIU items can wait.', 'TKP padat bacaan: 45 skenario masing-masing tiga atau empat baris. Pada 47 detik per soal, metodenya baca sekali (jangan baca ulang), sebutkan dimensi, temukan 1 dan 5, konfirmasi. Peserta yang terlambat mencapai TKP menjawab sepuluh terakhir kurang dari lima belas detik masing-masing dan mengumpulkan nilai 2 di sana; latihan bagian Lab melaporkan skormu pada soal 36 sampai 45 secara terpisah agar polanya terlihat. Jika titik periksa TIU meleset, jangan kompensasi dengan mengebut TKP: nilai 3 yang dipilih tenang mengalahkan nilai 2 yang dipilih cepat, dan soal TIU bertanda bisa menunggu.'),
    sec('refresh', 'The judgement-mode switch', 'Pergantian mode pertimbangan', 'The TIU to TKP boundary is the moment most candidates carry computation mode into judgement items and pick the “clever” option. The switch is a ritual of thirty seconds at the checkpoint: breathe, say the six dimensions, say the ladder, then open TKP item 1 and name its dimension before reading the options. The Lab’s SKD-110 simulation prompts the ritual at the boundary; in the real test the prompt must be your own.', 'Batas TIU ke TKP adalah momen kebanyakan peserta membawa mode perhitungan ke soal pertimbangan dan memilih opsi “cerdik”. Pergantiannya adalah ritual tiga puluh detik pada titik periksa: bernapas, sebutkan enam dimensi, sebutkan tangga, lalu buka soal TKP 1 dan sebutkan dimensinya sebelum membaca opsi. Simulasi SKD-110 Lab mengingatkan ritual itu pada batasnya; di tes sungguhan pengingatnya harus milikmu sendiri.')
  ],
  diagram: flow('Exhibit 1: From profile to drill', 'Peraga 1: Dari profil ke latihan', 'What each band of the dimension profile asks for', 'Apa yang diminta tiap pita profil dimensi', [
    ['x', 'Under 3.5', 'Di bawah 3,5', 'A trap is firing; untimed drill with the ladder reason.', 'Satu jebakan bekerja; latihan tanpa batas waktu dengan alasan tangga.'],
    ['target', '3.5 to 4.2', '3,5 sampai 4,2', 'Second-best habit; the “4 or 5?” drill.', 'Kebiasaan terbaik kedua; latihan “4 atau 5?”.'],
    ['check', 'Above 4.2', 'Di atas 4,2', 'Green; keep warm with the section practice.', 'Hijau; jaga tetap hangat dengan latihan bagian.'],
    ['clock', 'Items 36 to 45', 'Soal 36 sampai 45', 'Scored separately; rushed 2s show here.', 'Dinilai terpisah; nilai 2 terburu-buru muncul di sini.']
  ]),
  compare: [cmp('Two readings of “4 or 5?”', 'Dua pembacaan “4 atau 5?”', 'A citizen complains that the website and the counter give different information.', 'Seorang warga mengeluh bahwa situs dan loket memberi informasi berbeda.', '“Give the citizen the correct information.” Done, polite, a 4.', '“Beri warga informasi yang benar.” Selesai, sopan, nilai 4.', '“Apologise, give the correct information, and report the mismatch so the website is fixed.” Serves this citizen and the next thousand. A 5.', '“Minta maaf, beri informasi yang benar, dan laporkan ketidaksesuaiannya agar situs diperbaiki.” Melayani warga ini dan seribu berikutnya. Nilai 5.', 'The 5 adds the second move; the question “does this fix the cause?” finds it.', 'Nilai 5 menambahkan langkah kedua; pertanyaan “apakah ini membereskan sebabnya?” menemukannya.')],
  scenario: scen('clock', 'In focus: items 36 to 45', 'Sorotan: soal 36 sampai 45', [['A candidate’s TKP section practice came in at 172 with a dimension profile that was green everywhere except the last ten items, where she scored a mean of 2.9 against 4.1 elsewhere. She had reached TKP at minute 70. The fix was in TIU (the skip rule), not in TKP; her next practice, started at minute 62, scored 196.', 'Latihan bagian TKP seorang peserta mendapat 172 dengan profil dimensi hijau di mana-mana kecuali sepuluh soal terakhir, dengan rata-rata 2,9 dibandingkan 4,1 di tempat lain. Ia mencapai TKP pada menit ke-70. Perbaikannya ada di TIU (aturan melewati), bukan di TKP; latihan berikutnya, dimulai pada menit ke-62, mendapat 196.']]),
  steps: [
    step('Drill 1 · Lowest dimension, untimed', 'Latihan 1 · Dimensi terendah, tanpa batas waktu', 'From your profile, drill the lowest dimension (nine items) with the ladder reason on every item until its mean passes 4.', 'Dari profilmu, latih dimensi terendah (sembilan soal) dengan alasan tangga pada tiap soal sampai rata-ratanya melewati 4.', 'Note which trap fired; it will fire in other dimensions too.', 'Catat jebakan mana yang bekerja; ia akan bekerja di dimensi lain juga.'),
    step('Drill 2 · “4 or 5?”', 'Latihan 2 · “4 atau 5?”', 'Twenty scenarios showing only the two top options. Choose the 5; read why.', 'Dua puluh skenario yang hanya menampilkan dua opsi teratas. Pilih 5; baca alasannya.', 'The share of correct picks here predicts your second-best share on the next full set.', 'Porsi pilihan benar di sini meramalkan porsi terbaik keduamu pada set penuh berikutnya.'),
    step('Drill 3 · TKP section practice', 'Latihan 3 · Latihan bagian TKP', 'Forty-five items, 35 minutes, after a thirty-second judgement-mode ritual. Read the profile, the second-best share and the items 36 to 45 line.', 'Empat puluh lima soal, 35 menit, setelah ritual mode pertimbangan tiga puluh detik. Baca profil, porsi terbaik kedua, dan baris soal 36 sampai 45.', 'Three numbers, three fixes: profile to untimed drill, share to “4 or 5?”, last-ten to TIU pacing.', 'Tiga angka, tiga perbaikan: profil ke latihan tanpa batas waktu, porsi ke “4 atau 5?”, sepuluh terakhir ke tempo TIU.')
  ],
  mistakes: mist([['Rereading scenarios', 'Membaca ulang skenario', 'Read once; name the dimension; rank from the ends.', 'Baca sekali; sebutkan dimensi; urutkan dari ujung.'], ['Racing TKP to recover TIU time', 'Mengebut TKP untuk memulihkan waktu TIU', 'A calm 3 beats a fast 2; flags can wait.', 'Nilai 3 yang tenang mengalahkan nilai 2 yang cepat; tanda bisa menunggu.'], ['Drilling all six dimensions at once', 'Melatih enam dimensi sekaligus', 'Lowest first, until its mean passes 4.', 'Terendah dulu, sampai rata-ratanya melewati 4.'], ['Skipping the mode switch', 'Melewati pergantian mode', 'Thirty seconds at the boundary; the first three items set the mode.', 'Tiga puluh detik di batas; tiga soal pertama menetapkan mode.']]),
  glossary: gl([['Dimension profile', 'Profil dimensi', 'Mean score per dimension out of 5.', 'Skor rata-rata per dimensi dari 5.'], ['“4 or 5?” drill', 'Latihan “4 atau 5?”', 'Only the two top options shown; choose the 5.', 'Hanya dua opsi teratas ditampilkan; pilih 5.'], ['Last-ten line', 'Baris sepuluh terakhir', 'Separate score for items 36 to 45; shows rushing.', 'Skor terpisah untuk soal 36 sampai 45; menunjukkan terburu-buru.'], ['Judgement mode', 'Mode pertimbangan', 'The reading stance TKP needs after TIU’s computation.', 'Sikap membaca yang dibutuhkan TKP setelah perhitungan TIU.'], ['Procedure-only trap', 'Jebakan prosedur-saja', 'Following the letter while the citizen stays unserved.', 'Mengikuti bunyi aturan sementara warga tak terlayani.'], ['Section practice', 'Latihan bagian', 'A whole TKP section at test length and pace.', 'Satu bagian TKP utuh sepanjang dan secepat tes.']]),
  checks: [
    chk('A dimension with a mean of 3.2 most likely contains …', 'Dimensi dengan rata-rata 3,2 kemungkinan besar memuat …', [['only 4s', 'hanya nilai 4'], ['1s and 2s from a trap that fires there', 'nilai 1 dan 2 dari jebakan yang bekerja di sana'], ['blanks', 'kosong'], ['perfect answers', 'jawaban sempurna']], 1, 'Below 3.5 means harmful or avoiding picks; drill untimed with the ladder.', 'Di bawah 3,5 berarti pilihan merugikan atau menghindar; latih tanpa batas waktu dengan tangga.'),
    chk('The question that turns a 4 into a 5 is …', 'Pertanyaan yang mengubah 4 menjadi 5 adalah …', [['“is this polite?”', '“apakah ini sopan?”'], ['“does this fix the cause, or only the symptom?”', '“apakah ini membereskan sebabnya, atau hanya gejalanya?”'], ['“is this what my manager would do?”', '“apakah ini yang akan dilakukan manajerku?”'], ['“is this the longest option?”', '“apakah ini opsi terpanjang?”']], 1, 'The 5 acts and repairs; the 4 acts once.', 'Nilai 5 bertindak dan memperbaiki; nilai 4 bertindak sekali.'),
    chk('If you reach TKP late, you should …', 'Jika kamu mencapai TKP terlambat, sebaiknya …', [['answer the last ten at random', 'jawab sepuluh terakhir secara acak'], ['keep the calm method; a 3 beats a rushed 2', 'pertahankan metode tenang; nilai 3 mengalahkan nilai 2 terburu-buru'], ['go back to TIU first', 'kembali ke TIU dulu'], ['leave the last ten blank', 'biarkan sepuluh terakhir kosong']], 1, 'Rushed 2s and blanks cost more than any TIU flag could recover.', 'Nilai 2 terburu-buru dan kosong merugikan lebih dari yang bisa dipulihkan tanda TIU mana pun.')
  ],
  tool: tool('section:tkp', 'TKP section practice and the “4 or 5?” drill', 'Latihan bagian TKP dan latihan “4 atau 5?”', 'Forty-five items in 35 minutes with the judgement ritual, dimension profile, second-best share and the last-ten line; plus the “4 or 5?” drill and per-dimension untimed drills with the ladder reason.', 'Empat puluh lima soal dalam 35 menit dengan ritual pertimbangan, profil dimensi, porsi terbaik kedua, dan baris sepuluh terakhir; plus latihan “4 atau 5?” dan latihan tanpa batas waktu per dimensi dengan alasan tangga.'),
  takeaways: take([['Drill the lowest dimension until its mean passes 4.', 'Latih dimensi terendah sampai rata-ratanya melewati 4.'], ['“Does this fix the cause?” converts 4s into 5s.', '“Apakah ini membereskan sebabnya?” mengubah 4 menjadi 5.'], ['Thirty seconds at the boundary; never race the last ten.', 'Tiga puluh detik di batas; jangan pernah mengebut sepuluh terakhir.']]),
  resources: res('Honesty block', 'Blok kejujuran', 'On every TKP panel.', 'Di setiap panel TKP.', [['The notice', 'Pemberitahuan', 'Verbatim.', 'Apa adanya.', [[KEYNOTE.en, KEYNOTE.id], [NOTICE.en, NOTICE.id]]]])
});

const L1218 = lesson({
  n: '12.18', kind: 'interactive', dur: dur(110, b('the simulation', 'simulasi')),
  title: b('SKD-110 CAT Simulation and Report', 'Simulasi CAT SKD-110 dan Laporan'),
  overview: b('The Track C checkpoint: 110 original items in the config blueprint, 100 minutes on one global timer, question grid, doubt flag, auto-submit, then the score against the configured thresholds for your formation, the three section grids, the TKP dimension profile, the error log and the recommendation. This lesson explains how to sit it, what the report says and does not say, and how the two weeks after it are planned. The simulation is a Metanoia practice form in an SKD-like format; it imitates no institution’s interface or brand.', 'Titik periksa Jalur C: 110 soal asli dalam kisi-kisi konfigurasi, 100 menit pada satu pengatur waktu global, kisi soal, tanda ragu, kirim otomatis, lalu skor terhadap ambang batas yang dikonfigurasi untuk formasimu, tiga kisi bagian, profil dimensi TKP, catatan kesalahan, dan rekomendasi. Pelajaran ini menjelaskan cara mengerjakannya, apa yang dikatakan dan tidak dikatakan laporan, dan bagaimana dua minggu sesudahnya direncanakan. Simulasinya adalah formulir latihan Metanoia dalam format mirip SKD; tidak meniru antarmuka atau merek lembaga mana pun.'),
  objectives: [b('Sit 110 items in 100 minutes with the three checkpoints and the grid.', 'Mengerjakan 110 soal dalam 100 menit dengan tiga titik periksa dan kisi.'), b('Read the report against your formation’s thresholds.', 'Membaca laporan terhadap ambang formasimu.'), b('Separate section failures into knowledge, pace and judgement causes.', 'Memisahkan kegagalan bagian menjadi sebab pengetahuan, tempo, dan pertimbangan.'), b('Plan two weeks from the report and the plan tracker.', 'Merencanakan dua minggu dari laporan dan pelacak rencana.')],
  readFirst: rf('The simulation', 'Simulasi', 'Sit it once, read it three ways, plan from it.', 'Kerjakan sekali, baca tiga cara, rencanakan darinya.', [
    ['110 in 100', '110 dalam 100', [['Checkpoints 20, 62, 97; grid; doubt flag; auto-submit.', 'Titik periksa 20, 62, 97; kisi; tanda ragu; kirim otomatis.'], ['No pause, no lookups, the real hour, the real posture.', 'Tanpa jeda, tanpa mencari, jam sungguhan, postur sungguhan.']]],
    ['The report', 'Laporan', [['Score per section against your formation’s thresholds, with the decree and the date.', 'Skor per bagian terhadap ambang formasimu, dengan keputusan dan tanggalnya.'], ['Three grids, a TKP profile, the log, the recommendation.', 'Tiga kisi, profil TKP, catatan, rekomendasi.']]],
    ['What it is not', 'Apa yang bukan', [['A Metanoia practice form; not a prediction of your real score or rank.', 'Formulir latihan Metanoia; bukan ramalan skor atau peringkat sungguhanmu.'], ['Thresholds are the floor; the previous cycle’s last invited score is the target.', 'Ambang adalah lantai; skor terakhir yang diundang siklus sebelumnya adalah target.']]]
  ]),
  sections: [
    sec('laptop', 'Sitting it', 'Mengerjakannya', 'Choose the hour of your real session. Quiet room, water, scrap paper and a pen, phone away, the device you will not be allowed to use on the day but the posture you will have to hold: a desk and a chair, not a bed. Start the simulation; the three checkpoints are shown once at the start and never again, like the real test. The grid shows answered, flagged and unanswered; the global timer counts down; at zero the form submits itself. Section order is yours; the default is TWK, TIU, TKP. Do not pause (there is no pause), do not look anything up, do not stop early: the report is only as honest as the sitting.', 'Pilih jam sesi sungguhanmu. Ruangan tenang, air, kertas coret dan pena, ponsel dijauhkan, perangkat yang tidak akan boleh kamu pakai pada harinya tetapi postur yang harus kamu pertahankan: meja dan kursi, bukan tempat tidur. Mulai simulasi; tiga titik periksa ditampilkan sekali di awal dan tidak lagi, seperti tes sungguhan. Kisi menampilkan terjawab, ditandai, dan belum terjawab; pengatur waktu global menghitung mundur; pada nol formulir mengirim dirinya sendiri. Urutan bagian adalah milikmu; bawaannya TWK, TIU, TKP. Jangan berjeda (tidak ada jeda), jangan mencari apa pun, jangan berhenti lebih awal: laporan hanya sejujur duduknya.'),
    sec('chart', 'Reading the report three ways', 'Membaca laporan tiga cara', 'First, the <b>threshold line</b>: your three section scores next to your formation’s thresholds from the config (decree number and verified date printed), pass or fail per section, total, and the “estimate if no blanks” (your score plus roughly twelve points per ten blanks on TWK and TIU, since each blank answered at the base rate is worth about one point). Second, the <b>cause split</b> per section: knowledge (TWK sub-types red with “did not understand”), pace (TIU items flagged or answered under ten seconds; TKP items 36 to 45 under the mean), judgement (TKP dimension profile and second-best share). Third, the <b>recommendation</b> with its one-line reason: the section furthest below its threshold gets the next two weeks, split by cause. A section above its threshold but below the previous cycle’s last invited score is amber, not green.', 'Pertama, <b>baris ambang</b>: tiga skor bagianmu di samping ambang formasimu dari konfigurasi (nomor keputusan dan tanggal verifikasi dicetak), lulus atau gagal per bagian, total, dan “estimasi jika tanpa kosong” (skormu plus sekitar dua belas poin per sepuluh kosong pada TWK dan TIU, karena tiap kosong yang dijawab dengan peluang dasar bernilai sekitar satu poin). Kedua, <b>pemisahan sebab</b> per bagian: pengetahuan (sub-tipe TWK merah dengan “belum paham”), tempo (soal TIU ditandai atau dijawab kurang dari sepuluh detik; soal TKP 36 sampai 45 di bawah rata-rata), pertimbangan (profil dimensi TKP dan porsi terbaik kedua). Ketiga, <b>rekomendasi</b> dengan alasan satu barisnya: bagian yang paling jauh di bawah ambangnya mendapat dua minggu berikutnya, dibagi per sebab. Bagian di atas ambangnya tetapi di bawah skor terakhir yang diundang siklus sebelumnya adalah kuning, bukan hijau.'),
    sec('calendar', 'The two weeks after', 'Dua minggu sesudahnya', 'Week 1: the failing or weakest section, by cause. Knowledge: lesson sections and untimed drills on the red sub-types, three sessions. Pace: TIU section practice twice with the skip rule, and the budget card. Judgement: the lowest TKP dimension untimed, then “4 or 5?”. Week 2: section practice in all three sections on alternate days, the focus loop on everything missed, and the second simulation on day 14 at the same hour. The plan tracker records adherence; the second report prints it next to the score. If the second simulation shows the same cause split, the plan was not run, and the tracker says so.', 'Minggu 1: bagian yang gagal atau terlemah, per sebab. Pengetahuan: bagian pelajaran dan latihan tanpa batas waktu pada sub-tipe merah, tiga sesi. Tempo: latihan bagian TIU dua kali dengan aturan melewati, dan kartu anggaran. Pertimbangan: dimensi TKP terendah tanpa batas waktu, lalu “4 atau 5?”. Minggu 2: latihan bagian di ketiga bagian pada hari berselang, putaran fokus pada semua yang salah, dan simulasi kedua pada hari ke-14 pada jam yang sama. Pelacak rencana mencatat kepatuhan; laporan kedua mencetaknya di samping skor. Jika simulasi kedua menunjukkan pemisahan sebab yang sama, rencana tidak dijalankan, dan pelacak mengatakannya.'),
    sec('shieldTick', 'What the simulation is and is not', 'Apa simulasi itu dan apa yang bukan', 'It is a Metanoia practice form: 110 original items in the config blueprint, scored by the config rules, compared with the config thresholds, in a layout that reproduces the CAT’s behaviours (grid, flag, timer, auto-submit, on-screen score) and not its appearance. It is not a reproduction of any official form, it is not an imitation of any institution’s interface or brand, and its score is not a prediction of your real score, your rank, or your formation’s cut. The real items are different; the real screen looks different; the real thresholds are whatever the current decree says. The report says all of this on its first line.', 'Ini formulir latihan Metanoia: 110 soal asli dalam kisi-kisi konfigurasi, dinilai dengan aturan konfigurasi, dibandingkan dengan ambang konfigurasi, dalam tata letak yang mereproduksi perilaku CAT (kisi, tanda, pengatur waktu, kirim otomatis, skor di layar) dan bukan tampilannya. Ini bukan reproduksi formulir resmi mana pun, bukan tiruan antarmuka atau merek lembaga mana pun, dan skornya bukan ramalan skor sungguhanmu, peringkatmu, atau ambang formasimu. Soal sungguhan berbeda; layar sungguhan tampak berbeda; ambang sungguhan adalah apa pun yang dikatakan keputusan yang berlaku. Laporan mengatakan semua ini di baris pertamanya.')
  ],
  diagram: flow('Exhibit 1: The report, three ways', 'Peraga 1: Laporan, tiga cara', 'Threshold line, cause split, recommendation', 'Baris ambang, pemisahan sebab, rekomendasi', [
    ['flag', 'Threshold line', 'Baris ambang', 'Three sections against your formation’s bars, decree and date printed.', 'Tiga bagian terhadap batas formasimu, keputusan dan tanggal dicetak.'],
    ['search', 'Cause split', 'Pemisahan sebab', 'Knowledge, pace, judgement per section.', 'Pengetahuan, tempo, pertimbangan per bagian.'],
    ['compass', 'Recommendation', 'Rekomendasi', 'The weakest section, by cause, with a one-line reason.', 'Bagian terlemah, per sebab, dengan alasan satu baris.'],
    ['calendar', 'Two weeks', 'Dua minggu', 'Week 1 by cause; week 2 all sections; day 14 second simulation.', 'Minggu 1 per sebab; minggu 2 semua bagian; hari ke-14 simulasi kedua.']
  ]),
  compare: [cmp('Two readings of a fail', 'Dua pembacaan kegagalan', 'TWK 75, TIU 70, TKP 180 against 65 / 80 / 166.', 'TWK 75, TIU 70, TKP 180 terhadap 65 / 80 / 166.', '“Failed TIU, I am bad at maths.” Two weeks of arithmetic drills. Second simulation: TIU 75.', '“Gagal TIU, aku lemah matematika.” Dua minggu latihan aritmetika. Simulasi kedua: TIU 75.', 'Cause split: nine TIU items answered under ten seconds in the last six minutes; sub-types green when answered in time. Pace, not knowledge. Two TIU section practices with the skip rule. Second simulation: TIU 95.', 'Pemisahan sebab: sembilan soal TIU dijawab kurang dari sepuluh detik dalam enam menit terakhir; sub-tipe hijau saat dijawab tepat waktu. Tempo, bukan pengetahuan. Dua latihan bagian TIU dengan aturan melewati. Simulasi kedua: TIU 95.', 'The cause split chooses the fix; the score alone chooses the wrong one.', 'Pemisahan sebab memilih perbaikannya; skor sendirian memilih yang salah.')],
  scenario: scen('laptop', 'In focus: the first line', 'Sorotan: baris pertama', [['A candidate posted her simulation score in a study group as “my SKD score”. A friend who had sat the real test the year before pointed at the report’s first line: a Metanoia practice form, scored against config thresholds, not a prediction. She reread it as a diagnosis and found the two sub-types that had cost her; the real test, six weeks later, was a different set of items and the same two sub-types, now green.', 'Seorang peserta mengunggah skor simulasinya di grup belajar sebagai “skor SKD-ku”. Seorang teman yang mengikuti tes sungguhan tahun sebelumnya menunjuk baris pertama laporan: formulir latihan Metanoia, dinilai terhadap ambang konfigurasi, bukan ramalan. Ia membacanya ulang sebagai diagnosis dan menemukan dua sub-tipe yang merugikannya; tes sungguhan, enam minggu kemudian, adalah set soal yang berbeda dan dua sub-tipe yang sama, kini hijau.']]),
  steps: [
    step('Step 1 · Sit the SKD-110', 'Langkah 1 · Kerjakan SKD-110', 'Real hour, desk and chair, checkpoints 20, 62, 97 memorised, the judgement ritual at the TIU to TKP boundary. No pause, no lookups.', 'Jam sungguhan, meja dan kursi, titik periksa 20, 62, 97 dihafal, ritual pertimbangan pada batas TIU ke TKP. Tanpa jeda, tanpa mencari.', 'Record the three section scores and the total as Dossier item 3; the report stores the rest.', 'Catat tiga skor bagian dan totalnya sebagai butir Dossier 3; laporan menyimpan sisanya.'),
    step('Step 2 · Read it three ways', 'Langkah 2 · Baca tiga cara', 'Threshold line, cause split, recommendation. Tag every miss with a learner tag before leaving the review.', 'Baris ambang, pemisahan sebab, rekomendasi. Tandai setiap kesalahan dengan tanda pelajar sebelum meninggalkan tinjauan.', 'Write one sentence per section: “TIU failed on pace: nine rushed items”, not “TIU 70”.', 'Tulis satu kalimat per bagian: “TIU gagal karena tempo: sembilan soal terburu-buru”, bukan “TIU 70”.'),
    step('Step 3 · Fourteen sessions in the tracker', 'Langkah 3 · Empat belas sesi di pelacak', 'Week 1 by cause, week 2 all sections, day 14 the second simulation. Enter them in the plan tracker now.', 'Minggu 1 per sebab, minggu 2 semua bagian, hari ke-14 simulasi kedua. Masukkan ke pelacak rencana sekarang.', 'Adherence is printed next to the second score; the two explain each other.', 'Kepatuhan dicetak di samping skor kedua; keduanya saling menjelaskan.')
  ],
  mistakes: mist([['Reading the total', 'Membaca total', 'Sections against thresholds; one failing section is a fail.', 'Bagian terhadap ambang; satu bagian gagal adalah gagal.'], ['Fixing the score instead of the cause', 'Memperbaiki skor alih-alih sebab', 'Knowledge, pace or judgement; each has its own two weeks.', 'Pengetahuan, tempo, atau pertimbangan; masing-masing punya dua minggunya.'], ['Sitting it in bed at midnight', 'Mengerjakannya di tempat tidur tengah malam', 'Real hour, real posture, or the report lies.', 'Jam sungguhan, postur sungguhan, atau laporan berbohong.'], ['Quoting the score as a prediction', 'Mengutip skor sebagai ramalan', 'A practice form against config thresholds; the first line says so.', 'Formulir latihan terhadap ambang konfigurasi; baris pertama mengatakannya.']]),
  glossary: gl([['SKD-110', 'SKD-110', 'The Lab’s full simulation: 110 items, 100 minutes, config blueprint and scoring.', 'Simulasi penuh Lab: 110 soal, 100 menit, kisi-kisi dan penilaian konfigurasi.'], ['Threshold line', 'Baris ambang', 'Section scores against the formation’s thresholds with decree and date.', 'Skor bagian terhadap ambang formasi dengan keputusan dan tanggal.'], ['Cause split', 'Pemisahan sebab', 'Knowledge, pace, judgement per section.', 'Pengetahuan, tempo, pertimbangan per bagian.'], ['Auto-submit', 'Kirim otomatis', 'The form submits itself at zero on the global timer.', 'Formulir mengirim dirinya sendiri pada nol di pengatur waktu global.'], ['Estimate if no blanks', 'Estimasi jika tanpa kosong', 'Score plus about twelve points per ten TWK or TIU blanks.', 'Skor plus sekitar dua belas poin per sepuluh kosong TWK atau TIU.'], ['Adherence', 'Kepatuhan', 'Sessions done over planned, printed with the next report.', 'Sesi selesai dibagi direncanakan, dicetak dengan laporan berikutnya.']]),
  checks: [
    chk('The first line of the SKD-110 report says that …', 'Baris pertama laporan SKD-110 mengatakan bahwa …', [['your score predicts your real result', 'skormu meramalkan hasil sungguhanmu'], ['it is a Metanoia practice form scored against config thresholds, not a prediction', 'ini formulir latihan Metanoia yang dinilai terhadap ambang konfigurasi, bukan ramalan'], ['you have passed', 'kamu telah lulus'], ['the items are official', 'soalnya resmi']], 1, 'Honest framing on every report.', 'Pembingkaian jujur di setiap laporan.'),
    chk('A TIU fail with green sub-types but nine items answered under ten seconds is a … problem.', 'TIU gagal dengan sub-tipe hijau tetapi sembilan soal dijawab kurang dari sepuluh detik adalah masalah …', [['knowledge', 'pengetahuan'], ['pace', 'tempo'], ['judgement', 'pertimbangan'], ['device', 'perangkat']], 1, 'The cause split points at the skip rule and the checkpoints.', 'Pemisahan sebab menunjuk aturan melewati dan titik periksa.'),
    chk('How long between the first and second simulation?', 'Berapa lama antara simulasi pertama dan kedua?', [['one day', 'satu hari'], ['fourteen days of planned sessions', 'empat belas hari sesi terencana'], ['one hour', 'satu jam'], ['never repeat', 'jangan pernah mengulang']], 1, 'Enough work to move the cause split; the tracker prints adherence.', 'Kerja yang cukup untuk menggerakkan pemisahan sebab; pelacak mencetak kepatuhan.')
  ],
  tool: tool('cat:skd110', 'The SKD-110 simulation', 'Simulasi SKD-110', '110 original items, 100 minutes, one global timer, grid, doubt flag, auto-submit; the report against your formation’s thresholds with decree and date, three section grids, TKP profile, error log and recommendation. Metanoia practice form in an SKD-like format; not an imitation of any institution’s interface or brand.', '110 soal asli, 100 menit, satu pengatur waktu global, kisi, tanda ragu, kirim otomatis; laporan terhadap ambang formasimu dengan keputusan dan tanggal, tiga kisi bagian, profil TKP, catatan kesalahan, dan rekomendasi. Formulir latihan Metanoia dalam format mirip SKD; bukan tiruan antarmuka atau merek lembaga mana pun.', 'Start the simulation →', 'Mulai simulasi →'),
  takeaways: take([['Real hour, real posture, three checkpoints, no pause.', 'Jam sungguhan, postur sungguhan, tiga titik periksa, tanpa jeda.'], ['Threshold line, cause split, recommendation: read all three.', 'Baris ambang, pemisahan sebab, rekomendasi: baca ketiganya.'], ['A practice form, not a prediction; two planned weeks, then again.', 'Formulir latihan, bukan ramalan; dua minggu terencana, lalu lagi.']]),
  resources: res('Verification', 'Verifikasi', 'Before you trust a threshold.', 'Sebelum memercayai ambang.', [['Config panel', 'Panel konfigurasi', 'Decree and date.', 'Keputusan dan tanggal.', [['Thresholds, counts and timing are the config’s 2024-cycle values (KepmenPAN-RB No. 321/2024), verified on the date shown in the Lab; your cycle’s decree may differ. The previous cycle’s last invited score for your formation, if published, is the realistic target.', 'Ambang, jumlah, dan waktu adalah nilai siklus 2024 konfigurasi (KepmenPAN-RB No. 321/2024), diverifikasi pada tanggal yang ditampilkan di Lab; keputusan siklusmu mungkin berbeda. Skor terakhir yang diundang siklus sebelumnya untuk formasimu, jika dipublikasikan, adalah target yang realistis.'], [NOTICE.en, NOTICE.id]]]])
});

module.exports = { lessons: [L1215, L1216, L1217, L1218] };
